# Surah Yunus (chapter 10) — part 8: ayat 71-80 (IDs 1435-1444)
SURAH = 10

ENTRIES = {
1435: (
"اور — ان پر — نوح کا — واقعہ — پڑھو — جب — انہوں نے — اپنی قوم سے کہا — اے میری قوم — اگر — میرا — رہنا — اور — اللہ کی آیات — سے تمہیں نصیحت کرنا — تم — پر — بھاری پڑتا ہے — تو — میں — نے — اللہ پر — بھروسہ کیا — پس — اپنا — اور — اپنے شریکوں — کا — کام — پختہ کر لو — پھر — تمہارا — وہ — کام — تم — پر — چھپا نہ رہے — پھر — مجھ پر — فیصلہ کر دو — اور مجھے — مہلت نہ دو",
"""۱۔ نوحؑ — قوم کے روسز — سے — نمٹنے کے لیے — اللہ پر توکل کرتے ہیں۔
۲۔ ’’وَاتْلُ عَلَيْهِمْ نَبَأَ نُوحٍ إِذْ قَالَ لِقَوْمِهِ يَا قَوْمِ إِن كَانَ كَبُرَ عَلَيْكُم مَّقَامِي وَتَذْكِيرِي بِآيَاتِ اللَّهِ فَعَلَى اللَّهِ تَوَكَّلْتُ فَأَجْمِعُوا أَمْرَكُمْ وَشُرَكَاءَكُمْ ثُمَّ لَا يَكُن أَمْرُكُمْ عَلَيْكُمْ غُمَّةً ثُمَّ اقْضُوا إِلَيَّ وَلَا تُنظِرُونِ‘‘ — اور — ان پر — نوح کا — واقعہ — پڑھو — جب — انہوں نے — اپنی قوم سے کہا — اے میری قوم — اگر — میرا — رہنا — اور — اللہ کی آیات — سے تمہیں نصیحت کرنا — تم — پر — بھاری پڑتا ہے — تو — میں — نے — اللہ پر — بھروسہ کیا — پس — اپنا — اور — اپنے شریکوں — کا — کام — پختہ کر لو — پھر — تمہارا — وہ — کام — تم — پر — چھپا نہ رہے — پھر — مجھ پر — فیصلہ کر دو — اور مجھے — مہلت نہ دو — یعنی نوحؑ — قوم سے فرماتے ہیں — اگر میرا وعظ — بھاری ہے — تو — میں نے اللہ پر توکل کیا — تم — اپنا سب کچھ جمع کر کے — مجھ پر حملہ — کر سکتے ہو — مگر — میں — ڈرتا نہیں۔
۳۔ عملی سبق: حق پر — قائم رہو؛ دشمن — اللہ کی اجازت — سے — زیادہ — کچھ نہیں کر سکتا۔"""
),
1436: (
"پس — اگر — تم — منہ موڑ لو — تو — میں — نے — تم — سے — کوئی بدلہ نہیں مانگا — میرا بدلہ — صرف اللہ — کے — ذمے ہے — اور — مجھے — حکم دیا گیا — کہ — میں مسلمانوں — میں سے ہوں",
"""۱۔ نوحؑ — رسالت کا کوئی بدلہ — نہیں مانگتے۔
۲۔ ’’فَإِن تَوَلَّيْتُمْ فَمَا سَأَلْتُكُم مِّنْ أَجْرٍ إِنْ أَجْرِيَ إِلَّا عَلَى اللَّهِ وَأُمِرْتُ أَنْ أَكُونَ مِنَ الْمُسْلِمِينَ‘‘ — پس — اگر — تم — منہ موڑ لو — تو — میں — نے — تم — سے — کوئی بدلہ نہیں مانگا — میرا بدلہ — صرف اللہ — کے — ذمے ہے — اور — مجھے — حکم دیا گیا — کہ — میں مسلمانوں — میں سے ہوں — یعنی نوحؑ فرماتے ہیں — اگر تم منہ موڑو — تو میں نے — بدلہ نہیں مانگا — میرا بدلہ — صرف اللہ — کے ذمے ہے — اور مجھے مسلمان بننے کا — حکم دیا گیا ہے۔
۳۔ عملی سبق: حق کا پیغام — بلا اجرت — دیں۔"""
),
1437: (
"پس — انہوں نے — اسے جھٹلا دیا — تو — ہم — نے — اسے اور جو اس کے ساتھ — کشتی — میں تھے — نجات دی — اور — ہم — نے — ان — کو — خلیفے بنا دیا — اور — ہم — نے — ان — لوگوں کو — ہلاک کر دیا — جنہوں نے — ہماری آیات — کو جھٹلا دیا — پس — دیکھو — نتیجہ — کیا ہوا — ان — لوگوں کا جو — ڈرائے گئے تھے",
"""۱۔ نوحؑ اور کشتی والے — نجات یافته؛ جھٹلانے والے — ہلاک۔
۲۔ ’’فَكَذَّبُوهُ فَنَجَّيْنَاهُ وَمَن مَّعَهُ فِي الْفُلْكِ وَجَعَلْنَاهُمْ خَلَائِفَ وَأَغْرَقْنَا الَّذِينَ كَذَّبُوا بِآيَاتِنَا فَانظُرْ كَيْفَ كَانَ عَاقِبَۃُ الْمُنذَرِينَ‘‘ — پس — انہوں نے — اسے جھٹلا دیا — تو — ہم — نے — اسے اور جو اس کے ساتھ — کشتی — میں تھے — نجات دی — اور — ہم — نے — ان — کو — خلیفے بنا دیا — اور — ہم — نے — ان — لوگوں کو — ہلاک کر دیا — جنہوں نے — ہماری آیات — کو جھٹلا دیا — پس — دیکھو — نتیجہ — کیا ہوا — ان — لوگوں کا جو — ڈرائے گئے تھے — یعنی نوحؑ اور اہلِ کشتی — نجات پائے — باقی — ہلاک ہوئے؛ انجام — ڈرائے جانے والوں کا — دیکھو۔
۳۔ عملی سبق: جھٹلانے والوں کا انجام — ہمیشہ ہلاکت ہے۔"""
),
1438: (
"پھر — اس — کے بعد — ہم — نے — ان — کی طرف — رسول — بھیجے — ان — کی قوموں کی طرف — پس — وہ — واضح — نشانیاں — لے کر آئے — پس — وہ — ایمان — نہ لائے — اس — چیز پر جسے — انہوں نے — پہلے جھٹلا دیا تھا — اسی طرح — ہم — تجاوز کرنے والوں — کے — دلوں پر — مہر — لگا دیتے ہیں",
"""۱۔ نوحؑ کے بعد — رسول — بھیجے گئے — مگر — پہلے کی طرح — جھٹلاتے رہے۔
۲۔ ’’ثُمَّ بَعَثْنَا مِن بَعْدِهِ رُسُلًا إِلَىٰ قَوْمِهِمْ فَجَاءُوهُم بِالْبَيِّنَاتِ فَمَا كَانُوا لِيُؤْمِنُوا بِمَا كَذَّبُوا بِهِ مِن قَبْلُ كَذَٰلِكَ نَطْبَعُ عَلَىٰ قُلُوبِ الْمُعْتَدِينَ‘‘ — پھر — اس — کے بعد — ہم — نے — ان — کی طرف — رسول — بھیجے — ان — کی قوموں کی طرف — پس — وہ — واضح — نشانیاں — لے کر آئے — پس — وہ — ایمان — نہ لائے — اس — چیز پر جسے — انہوں نے — پہلے جھٹلا دیا تھا — اسی طرح — ہم — تجاوز کرنے والوں — کے — دلوں پر — مہر — لگا دیتے ہیں — یعنی نوحؑ کے بعد — رسول — بھیجے گئے — مگر — وہ ایمان — نہ لائے — جیسے پہلے جھٹلایا تھا؛ تجاوز کرنے والوں کے دل — مہر شدہ — ہوتے ہیں۔
۳۔ عملی سبق: مسلسل — جھٹلانا — دل کو — مہر — کردیتا ہے۔"""
),
1439: (
"پھر — ان — کے بعد — ہم — نے — موسیٰ اور ہارونؑ کو — فرعون اور اس کے سرداروں — کی طرف — اپنی — آیات — کے ساتھ — بھیجا — پس — وہ — متکبر ہو گئے — اور — وہ — مجرم قوم — تھے",
"""۱۔ موسیٰؑ و ہارونؑ — فرعون کی طرف بھیجے گئے۔
۲۔ ’’ثُمَّ بَعَثْنَا مِن بَعْدِهِم مُّوسَىٰ وَهَارُونَ إِلَىٰ فِرْعَوْنَ وَمَلَئِهِ بِآيَاتِنَا فَاسْتَكْبَرُوا وَكَانُوا قَوْمًا مُّجْرِمِينَ‘‘ — پھر — ان — کے بعد — ہم — نے — موسیٰ اور ہارونؑ کو — فرعون اور اس کے سرداروں — کی طرف — اپنی — آیات — کے ساتھ — بھیجا — پس — وہ — متکبر ہو گئے — اور — وہ — مجرم قوم — تھے — یعنی ان — کے بعد موسیٰؑ اور ہارونؑ — فرعون اور اس کے سرداروں کی طرف بھیجے گئے؛ وہ — متکبر اور مجرم تھے۔
۳۔ عملی سبق: تکبر — دلیل کا دشمن ہے؛ عاجزی — اختیار کرو۔"""
),
1440: (
"پس — جب — ہماری — طرف سے — حق — ان — کے پاس آیا — تو — کہا — یہ — تو — واضح جادو ہے",
"""۱۔ فرعون — حق کو — جادو سمجھا۔
۲۔ ’’فَلَمَّا جَاءَهُمُ الْحَقُّ مِنْ عِندِنَا قَالُوا إِنَّ هَٰذَا لَسِحْرٌ مُّبِينٌ‘‘ — پس — جب — ہماری — طرف سے — حق — ان — کے پاس آیا — تو — کہا — یہ — تو — واضح جادو ہے — یعنی جب اللہ کا حق — ان کے پاس آیا — انہوں نے کہا — یہ — واضح جادو ہے۔
۳۔ عملی سبق: حق — جسے جھٹلایا — جائے — اسے — جادو — کہا جاتا ہے۔"""
),
1441: (
"موسیٰ نے کہا — کیا — تم — حق — پر یہ — کہتے ہو — جب — وہ — تمہارے — پاس — آ چکا — کیا — یہ — جادو — ہے — اور — جادوگر — کامیاب — نہیں — ہوتے",
"""۱۔ موسیٰؑ — حق — اور — جادو — میں — تمیز — خود دلیل — سے۔
۲۔ ’’قَالَ مُوسَىٰ أَتَقُولُونَ لِلْحَقِّ لَمَّا جَاءَكُمْ أَسِحْرٌ هَٰذَا وَلَا يُفْلِحُ السَّاحِرُونَ‘‘ — موسیٰ نے کہا — کیا — تم — حق — پر یہ — کہتے ہو — جب — وہ — تمہارے — پاس — آ چکا — کیا — یہ — جادو — ہے — اور — جادوگر — کامیاب — نہیں — ہوتے — یعنی موسیٰؑ نے کہا — کیا تم حق آنے پر — اسے — جادو کہتے ہو — جادوگر — کبھی — کامیاب نہیں ہوتے۔
۳۔ عملی سبق: جادو — عارضی ہے؛ حق — مستقل — ہے۔"""
),
1442: (
"انہوں نے کہا — کیا — تم ہمارے پاس — اس — لیے آئے — کہ — ہمیں — اس — چیز سے پھیرو — جس — پر — ہم نے — اپنے باپ دادا — کو پایا — اور — زمین میں — تم دونوں — کی — بڑی — بزرگی — ہو جائے — اور — ہم — تم دونوں کو — ایمان نہیں — لائیں گے",
"""۱۔ فرعون اور سردار — حق کو — اپنے باپ دادا کا مذہب — سمجھے۔
۲۔ ’’قَالُوا أَجِئْتَنَا لِتَلْفِتَنَا عَمَّا وَجَدْنَا عَلَيْهِ آبَاءَنَا وَتَكُونَ لَكُمَا الْكِبْرِيَاءُ فِي الْأَرْضِ وَمَا نَحْنُ لَكُمَا بِمُؤْمِنِينَ‘‘ — انہوں نے کہا — کیا — تم ہمارے پاس — اس — لیے آئے — کہ — ہمیں — اس — چیز سے پھیرو — جس — پر — ہم نے — اپنے باپ دادا — کو پایا — اور — زمین میں — تم دونوں — کی — بڑی — بزرگی — ہو جائے — اور — ہم — تم دونوں کو — ایمان نہیں — لائیں گے — یعنی فرعون نے کہا — کیا — تم ہمیں اس سے پھیرنا چاہتے ہو — جس پر ہم نے — اپنے باپ دادا — کو پایا — تاکہ — زمین میں تم دونوں کی — بڑی — بزرگی ہو جائے — اور — ہم — تم دونوں پر — ایمان — نہیں لائیں گے۔
۳۔ عملی سبق: باپ دادا کی — تقلید — حق — کی جگہ — نہیں لے سکتی۔"""
),
1443: (
"اور — فرعون نے کہا — مجھے — ہر — استاد — جادوگر — لاؤ",
"""۱۔ فرعون — جادوگروں کو — طلب کرنے کا حکم دیتا ہے۔
۲۔ ’’وَقَالَ فِرْعَوْنُ ائْتُونِي بِكُلِّ سَاحِرٍ عَلِيمٍ‘‘ — اور — فرعون نے کہا — مجھے — ہر — استاد — جادوگر — لاؤ — یعنی فرعون — نے حکم دیا — مجھے — ہر استاد جادوگر — لاؤ۔
۳۔ عملی سبق: جھوٹے — ہمیشہ — دلیل — کے مقابلہ میں — طاقت — استعمال کرتے ہیں۔"""
),
1444: (
"پس — جب — جادوگر آئے — موسیٰ — نے — ان — سے کہا — پھینکو — جو — تم پھینکنا چاہتے ہو",
"""۱۔ موسیٰؑ — جادوگروں کو — اپنی حکمت عملی — بتاتے ہیں۔
۲۔ ’’فَلَمَّا جَاءَ السَّحَرَۃُ قَالَ لَهُم مُّوسَىٰ أَلْقُوا مَا أَنتُم مُّلْقُونَ‘‘ — پس — جب — جادوگر آئے — موسیٰ — نے — ان — سے کہا — پھینکو — جو — تم پھینکنا چاہتے ہو — یعنی جادوگر — آئے — تو موسیٰؑ نے کہا — پھینکو — جو — تم پھینکنا چاہتے ہو — پہلے — تم — کرو۔
۳۔ عملی سبق: پہلے اپنی کوشش کرو — پھر — اللہ — فیصلہ — کرے گا۔"""
),
}
